// newLibraryAPI builds a handler over a fresh store (no scan closure needed —
// every test here exercises the library CRUD/browse surface only).
func newLibraryAPI(t *testing.T) (http.Handler, *store.Store) {
	t.Helper()
	st := openAPIStore(t)
	h := New(Deps{AdminToken: adminToken, Store: st, Scan: func(context.Context, int64) (scan.Result, error) {
		return scan.Result{}, nil
	}})
	return h, st
}

// itoa64 renders a library id for a URL path segment.
func itoa64(id int64) string { return strconv.FormatInt(id, 10) }

// seedItem puts one item into a library with the given relative path.
func seedItem(t *testing.T, st *store.Store, libraryID int64, fileID, relPath string) {
	t.Helper()
	err := st.PutItem(context.Background(), store.Item{
		ID: "itm_" + fileID, ModuleID: "tv", LibraryID: libraryID, FileID: fileID,
		RelativePath: relPath, MediaType: "tv",
		Document: json.RawMessage(`{}`), SchemaVersion: 1,
	})
	if err != nil {
		t.Fatalf("PutItem %s: %v", fileID, err)
	}
}

// TestLibraryCreateDescription covers POST /api/v1/libraries with and without
// the optional description: both create, and the returned DTO carries the
// description persisted on the row (web-ui-phase-3 1.2).
func TestLibraryCreateDescription(t *testing.T) {
	h, st := newLibraryAPI(t)
	ctx := context.Background()

	t.Run("with_description", func(t *testing.T) {
		body := `{"module_id":"tv","root_path":"/media/desc","display_name":"TV","description":"Seasonal shows"}`
		resp := doRequest(t, h, http.MethodPost, "/api/v1/libraries", body, adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusCreated {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusCreated)
		}
		var lr libraryDTO
		if err := json.NewDecoder(resp.Body).Decode(&lr); err != nil {
			t.Fatalf("decode libraryDTO: %v", err)
		}
		if lr.Description != "Seasonal shows" {
			t.Fatalf("DTO description = %q, want %q", lr.Description, "Seasonal shows")
		}
		lib, err := st.GetLibrary(ctx, lr.ID)
		if err != nil {
			t.Fatalf("GetLibrary: %v", err)
		}
		if lib.Description != "Seasonal shows" {
			t.Fatalf("persisted description = %q, want %q", lib.Description, "Seasonal shows")
		}
	})

	t.Run("without_description_defaults_empty", func(t *testing.T) {
		body := `{"module_id":"tv","root_path":"/media/no-desc","display_name":"TV"}`
		resp := doRequest(t, h, http.MethodPost, "/api/v1/libraries", body, adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusCreated {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusCreated)
		}
		var lr libraryDTO
		if err := json.NewDecoder(resp.Body).Decode(&lr); err != nil {
			t.Fatalf("decode libraryDTO: %v", err)
		}
		if lr.Description != "" {
			t.Fatalf("DTO description = %q, want \"\"", lr.Description)
		}
		lib, err := st.GetLibrary(ctx, lr.ID)
		if err != nil {
			t.Fatalf("GetLibrary: %v", err)
		}
		if lib.Description != "" {
			t.Fatalf("persisted description = %q, want \"\"", lib.Description)
		}
	})
}

// TestLibraryListDescription covers GET /api/v1/libraries: every entry carries
// its description, "" when never set (web-ui-phase-3 1.2).
func TestLibraryListDescription(t *testing.T) {
	h, st := newLibraryAPI(t)
	if _, err := st.CreateLibrary(context.Background(), "tv", "/media/list-desc", "TV", "Seasonal shows"); err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	if _, err := st.CreateLibrary(context.Background(), "film", "/media/list-nodesc", "Film"); err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	resp := doRequest(t, h, http.MethodGet, "/api/v1/libraries", "", adminToken)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
	}
	var lr librariesResponse
	if err := json.NewDecoder(resp.Body).Decode(&lr); err != nil {
		t.Fatalf("decode librariesResponse: %v", err)
	}
	byRoot := map[string]string{}
	for _, l := range lr.Items {
		byRoot[l.RootPath] = l.Description
	}
	if byRoot["/media/list-desc"] != "Seasonal shows" {
		t.Fatalf("listed description = %q, want %q", byRoot["/media/list-desc"], "Seasonal shows")
	}
	if desc, ok := byRoot["/media/list-nodesc"]; !ok || desc != "" {
		t.Fatalf("listed description = %q (present=%t), want \"\" (empty string when unset)", desc, ok)
	}
}

// TestLibraryPatchUpdate covers PATCH /api/v1/libraries/{id}: present fields
// update the row, the response is 200 with the updated DTO, and a following
// GET /libraries reflects both fields (web-ui-phase-3 1.3).
func TestLibraryPatchUpdate(t *testing.T) {
	h, st := newLibraryAPI(t)
	id, err := st.CreateLibrary(context.Background(), "tv", "/media/patch", "tv_2024")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	path := "/api/v1/libraries/" + itoa64(id)

	t.Run("rename_and_describe", func(t *testing.T) {
		body := `{"display_name":"ongoing","description":"Seasonal shows still airing"}`
		resp := doRequest(t, h, http.MethodPatch, path, body, adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		var lr libraryDTO
		if err := json.NewDecoder(resp.Body).Decode(&lr); err != nil {
			t.Fatalf("decode libraryDTO: %v", err)
		}
		if lr.ID != id || lr.DisplayName != "ongoing" || lr.Description != "Seasonal shows still airing" {
			t.Fatalf("patched DTO = %+v", lr)
		}
		// GET /libraries reflects both fields.
		listResp := doRequest(t, h, http.MethodGet, "/api/v1/libraries", "", adminToken)
		defer listResp.Body.Close()
		var lrs librariesResponse
		if err := json.NewDecoder(listResp.Body).Decode(&lrs); err != nil {
			t.Fatalf("decode librariesResponse: %v", err)
		}
		for _, l := range lrs.Items {
			if l.ID == id && (l.DisplayName != "ongoing" || l.Description != "Seasonal shows still airing") {
				t.Fatalf("listed library after PATCH = %+v", l)
			}
		}
	})

	t.Run("absent_fields_leave_values_unchanged", func(t *testing.T) {
		body := `{"description":"updated desc only"}`
		resp := doRequest(t, h, http.MethodPatch, path, body, adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		var lr libraryDTO
		if err := json.NewDecoder(resp.Body).Decode(&lr); err != nil {
			t.Fatalf("decode libraryDTO: %v", err)
		}
		if lr.DisplayName != "ongoing" || lr.Description != "updated desc only" {
			t.Fatalf("partial PATCH changed absent field: %+v", lr)
		}
	})
}

// TestLibraryPatchImmutable covers the identity guard: root_path/module_id in
// the body is 400 bad_request with the row untouched; an unknown id is 404
// not_found (web-ui-phase-3 1.4).
func TestLibraryPatchImmutable(t *testing.T) {
	h, st := newLibraryAPI(t)
	id, err := st.CreateLibrary(context.Background(), "tv", "/media/immutable", "TV", "original desc")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}

	cases := []struct {
		name string
		body string
	}{
		{"root_path_present", `{"root_path":"/media/moved"}`},
		{"module_id_present", `{"module_id":"film"}`},
		{"both_present", `{"root_path":"/media/moved","module_id":"film","display_name":"X"}`},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			resp := doRequest(t, h, http.MethodPatch, "/api/v1/libraries/"+itoa64(id), tc.body, adminToken)
			defer resp.Body.Close()
			if resp.StatusCode != http.StatusBadRequest {
				t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusBadRequest)
			}
			if eb := decodeError(t, resp); eb.Error.Code != "bad_request" || eb.Error.Retryable {
				t.Fatalf("error body = %+v, want bad_request/non-retryable", eb.Error)
			}
			// The row is untouched.
			lib, err := st.GetLibrary(context.Background(), id)
			if err != nil {
				t.Fatalf("GetLibrary: %v", err)
			}
			if lib.RootPath != "/media/immutable" || lib.ModuleID != "tv" || lib.DisplayName != "TV" || lib.Description != "original desc" {
				t.Fatalf("rejected PATCH mutated the row: %+v", lib)
			}
		})
	}

	t.Run("unknown_id_not_found", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodPatch, "/api/v1/libraries/99999", `{"display_name":"X"}`, adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusNotFound {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusNotFound)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "not_found" {
			t.Fatalf("error code = %q, want not_found", eb.Error.Code)
		}
	})
}

// TestLibrarySummary covers GET /api/v1/libraries/{id}/summary: count +
// last-update aggregate, empty library → items 0 + "", unknown → 404,
// non-integer → 400 (web-ui-phase-3 1.5).
func TestLibrarySummary(t *testing.T) {
	h, st := newLibraryAPI(t)
	ctx := context.Background()

	libID, err := st.CreateLibrary(ctx, "tv", "/media/summary", "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	emptyID, err := st.CreateLibrary(ctx, "tv", "/media/summary-empty", "Empty")
	if err != nil {
		t.Fatalf("CreateLibrary empty: %v", err)
	}

	t.Run("counts_and_last_update", func(t *testing.T) {
		seedItem(t, st, libID, "fid-a", "A S01E01.mkv")
		time.Sleep(2 * time.Millisecond) // ensure a strictly later updated_at stamp
		seedItem(t, st, libID, "fid-b", "A S01E02.mkv")
		resp := doRequest(t, h, http.MethodGet, "/api/v1/libraries/"+itoa64(libID)+"/summary", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		var sr librarySummaryResponse
		if err := json.NewDecoder(resp.Body).Decode(&sr); err != nil {
			t.Fatalf("decode summary: %v", err)
		}
		if sr.LibraryID != libID || sr.Items != 2 {
			t.Fatalf("summary = %+v, want library_id=%d items=2", sr, libID)
		}
		// updated_at is the max item stamp: parseable RFC3339, and after the
		// later seed it must be strictly past the first item's write.
		stamp, err := time.Parse(time.RFC3339, sr.UpdatedAt)
		if err != nil {
			t.Fatalf("updated_at %q is not RFC3339: %v", sr.UpdatedAt, err)
		}
		if !stamp.After(time.Now().Add(-time.Minute)) {
			t.Fatalf("updated_at %q is not a recent max item stamp", sr.UpdatedAt)
		}
	})

	t.Run("empty_library", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/libraries/"+itoa64(emptyID)+"/summary", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		var raw map[string]json.RawMessage
		if err := json.NewDecoder(resp.Body).Decode(&raw); err != nil {
			t.Fatalf("decode raw: %v", err)
		}
		if string(raw["items"]) != "0" || string(raw["updated_at"]) != `""` {
			t.Fatalf("empty summary = %v, want items 0 and updated_at \"\"", raw)
		}
	})

	t.Run("unknown_id_not_found", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/libraries/99999/summary", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusNotFound {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusNotFound)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "not_found" {
			t.Fatalf("error code = %q, want not_found", eb.Error.Code)
		}
	})

	t.Run("non_integer_id_bad_request", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/libraries/abc/summary", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusBadRequest {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusBadRequest)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "bad_request" {
			t.Fatalf("error code = %q, want bad_request", eb.Error.Code)
		}
	})
}

// TestLibraryFolders covers GET /api/v1/libraries/{id}/folders: depth-1
// prefixes with counts, path-sorted, "" for top-level files, unknown → 404,
// non-integer → 400 (web-ui-phase-3 1.6).
func TestLibraryFolders(t *testing.T) {
	h, st := newLibraryAPI(t)
	ctx := context.Background()
	libID, err := st.CreateLibrary(ctx, "image", "/media/folders", "Photos")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	seedItem(t, st, libID, "fid-1", "2026/a.jpg")
	seedItem(t, st, libID, "fid-2", "2026/b.jpg")
	seedItem(t, st, libID, "fid-3", "nature/c.jpg")
	seedItem(t, st, libID, "fid-4", "root.jpg")

	t.Run("depth1_prefixes_sorted", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/libraries/"+itoa64(libID)+"/folders", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		var fr libraryFoldersResponse
		if err := json.NewDecoder(resp.Body).Decode(&fr); err != nil {
			t.Fatalf("decode folders: %v", err)
		}
		want := []folderDTO{{Path: "", Items: 1}, {Path: "2026", Items: 2}, {Path: "nature", Items: 1}}
		if len(fr.Folders) != len(want) {
			t.Fatalf("folders = %+v, want %+v", fr.Folders, want)
		}
		for i, w := range want {
			if fr.Folders[i] != w {
				t.Fatalf("folders[%d] = %+v, want %+v (path-sorted, \"\" for root files)", i, fr.Folders[i], w)
			}
		}
	})

	t.Run("unknown_id_not_found", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/libraries/99999/folders", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusNotFound {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusNotFound)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "not_found" {
			t.Fatalf("error code = %q, want not_found", eb.Error.Code)
		}
	})

	t.Run("non_integer_id_bad_request", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/libraries/abc/folders", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusBadRequest {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusBadRequest)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "bad_request" {
			t.Fatalf("error code = %q, want bad_request", eb.Error.Code)
		}
	})
}
